/*
 * macaddr.c - EXPERIMENTAL: the "MAC address" setting (kernel/macaddr.c).
 *
 * Stock uses the console's own address. Custom uses a saved one, which is
 * either typed in, or generated by Randomize (the console's own first three
 * bytes, the maker, plus three random bytes). Switching to Custom generates a
 * new one. Every change drops the Wi-Fi link, sends the address to the chip and
 * rejoins, since the access point knows the console by its address.
 *
 * The chip comes back on its factory address at every power-up (Wi-Fi off/on,
 * resume) and the driver no longer asks it, so a watcher re-sends the custom
 * address after each one, and boot sends it once the link is up.
 *
 * Commands (dispatch.c, from the Settings page and :1339):
 *   mac status | probe | stock | custom | random | set <addr> | cycle
 * The chosen mode and address are saved through wq_settings_note as
 * "mac state <0|1> <12 hex>"; the console's own address as "mac factory <12 hex>".
 */
#include <psp2/kernel/processmgr.h>   /* sceKernelGetProcessTimeWide */
#include <psp2/kernel/threadmgr.h>    /* threads, mutex               */
#include <psp2/kernel/rng.h>          /* sceKernelGetRandomNumber     */
#include <psp2/net/net.h>             /* sceNetGetMacAddress          */
#include <psp2/net/netctl.h>          /* sceNetCtlInetGet*            */
#include <string.h>

#include "macaddr.h"
#include "rxcycle.h"
#include "netjoin.h"
#include "settings_entry.h"           /* wq_settings_note */
#include "log.h"
#include "../include/wifiturbo.h"
#include "../include/wifiturbo_kernel_api.h"

extern int sceWlanGetConfiguration(void);   /* NID 0x70AF9BD6; &9 = radio on */

#define MAC_BOOT_WAIT_S   30                /* boot: wait this long for a power-up */
#define MAC_CTX_POLLS     20                /* RSSI reads to show the driver ctx */

static int hexval(char c)
{
	if (c >= '0' && c <= '9') return c - '0';
	if (c >= 'a' && c <= 'f') return c - 'a' + 10;
	if (c >= 'A' && c <= 'F') return c - 'A' + 10;
	return -1;
}

int wq_mac_parse(const char *s, uint8_t mac[6], int *why)
{
	int n = 0;
	uint8_t b[6];
	*why = 1;
	for (; *s && *s != ' '; s++) {
		if (*s == ':' || *s == '-' || *s == '.')
			continue;
		int v = hexval(*s);
		if (v < 0 || n >= 12)
			return -1;
		if (n & 1) b[n / 2] = (uint8_t)(b[n / 2] << 4 | v);
		else       b[n / 2] = (uint8_t)v;
		n++;
	}
	if (n != 12)
		return -1;
	if (b[0] & 1) { *why = 2; return -1; }
	int zero = 1, ff = 1;
	for (int i = 0; i < 6; i++) {
		if (b[i])         zero = 0;
		if (b[i] != 0xFF) ff = 0;
	}
	if (zero || ff) { *why = 3; return -1; }
	memcpy(mac, b, 6);
	*why = 0;
	return 0;
}

static const char *const k_why[4] = {
	"", "not 12 hex digits", "group (multicast) address - first byte must be even",
	"all-zero or broadcast address",
};

static char *put(char *p, char *end, const char *s)
{
	while (*s && p < end - 1) *p++ = *s++;
	*p = 0;
	return p;
}

static char *put_u(char *p, char *end, unsigned v)
{
	char t[12]; int n = 0;
	if (!v) t[n++] = '0';
	while (v) { t[n++] = (char)('0' + v % 10); v /= 10; }
	while (n && p < end - 1) *p++ = t[--n];
	*p = 0;
	return p;
}

static char *put_hex(char *p, char *end, unsigned v)
{
	static const char hx[] = "0123456789abcdef";
	int sh = 28;
	while (sh > 0 && !((v >> sh) & 15)) sh -= 4;
	for (; sh >= 0 && p < end - 1; sh -= 4)
		*p++ = hx[(v >> sh) & 15];
	*p = 0;
	return p;
}

static char *put_mac_sep(char *p, char *end, const uint8_t *m, int sep)
{
	const char *h = "0123456789ABCDEF";
	for (int i = 0; i < 6; i++) {
		if (i && sep && p < end - 1) *p++ = ':';
		if (p < end - 2) { *p++ = h[m[i] >> 4]; *p++ = h[m[i] & 15]; }
	}
	*p = 0;
	return p;
}

static char *put_mac(char *p, char *end, const uint8_t *m)
{
	return put_mac_sep(p, end, m, 1);
}

static void split(const uint8_t *m, unsigned *m0, unsigned *m1)
{
	*m0 = m[0] | m[1] << 8 | m[2] << 16 | (unsigned)m[3] << 24;
	*m1 = m[4] | m[5] << 8;
}

static void join(uint8_t *m, unsigned m0, unsigned m1)
{
	m[0] = (uint8_t)m0; m[1] = (uint8_t)(m0 >> 8); m[2] = (uint8_t)(m0 >> 16);
	m[3] = (uint8_t)(m0 >> 24); m[4] = (uint8_t)m1; m[5] = (uint8_t)(m1 >> 8);
}

/* The console's first three bytes + three random ones, never its own address.
 * Also used by the Settings page, so it knows the new address at once. */
void wq_mac_random(uint8_t m[6], const uint8_t factory[6])
{
	memcpy(m, factory, 3);
	do {
		uint32_t x = 0;
		if (sceKernelGetRandomNumber(&x, sizeof(x)) < 0) {   /* clock fallback */
			x = (uint32_t)sceKernelGetProcessTimeWide() * 2654435761u;
			x ^= x >> 15; x *= 0x2C1B3C6Du; x ^= x >> 12;
		}
		m[3] = (uint8_t)x; m[4] = (uint8_t)(x >> 8); m[5] = (uint8_t)(x >> 16);
	} while (!memcmp(m, factory, 6));
}

static int netctl_state(void)
{
	int st = -1;
	return sceNetCtlInetGetState(&st) == 0 ? st : -1;
}

static int radio_on(void)
{
	return (sceWlanGetConfiguration() & 9) != 0;
}

/* ---- state ---------------------------------------------------------------- */

static SceUID            g_mtx = -1;
static volatile int      g_mode;               /* 0 stock, 1 custom (saved)   */
static uint8_t           g_custom[6];
static uint8_t           g_saved_factory[6];
static volatile uint32_t g_applied_powerups;
static volatile int      g_retry;              /* last SET failed: retry      */
static volatile int      g_watch_started, g_job_busy;
static uint8_t           g_job_mac[6];
static volatile int      g_job_boot;
static volatile int      g_boot_rx_cycle;      /* the RX buffer preset cycles at boot */
static volatile int      g_fast;               /* boot: watch the power-up closely  */

static void save_state(void)
{
	char line[40], *p = line, *end = line + sizeof(line);
	p = put(p, end, g_mode ? "mac state 1 " : "mac state 0 ");
	put_mac_sep(p, end, g_custom, 0);
	wq_settings_note(line);
}

/* The kernel only learns the driver ctx once a chip command has gone through
 * the send helper. Reading the RSSI makes the driver send one. */
static int ensure_ctx(WqMacStatus *st)
{
	for (int i = 0; i < MAC_CTX_POLLS; i++) {
		if (wqMacAddr(WQ_MAC_OP_STATUS, 0, 0, st) == WQ_OK && st->ctx_seen)
			return WQ_OK;
		SceNetCtlInfo info;
		sceNetCtlInetGetInfo(SCE_NETCTL_INFO_GET_RSSI_DBM, &info);
		sceKernelDelayThread(500 * 1000);
	}
	return WQ_ERR_NOT_READY;
}

/* Remember the console's own address (shown on the Settings page while the
 * mode is Stock, and the base for Randomize). */
static void note_factory(const WqMacStatus *st)
{
	if (!st->have_factory || !memcmp(st->factory, g_saved_factory, 6))
		return;
	memcpy(g_saved_factory, st->factory, 6);
	char line[40], *p = line, *end = line + sizeof(line);
	p = put(p, end, "mac factory ");
	put_mac_sep(p, end, st->factory, 0);
	wq_settings_note(line);
}

/* Drop the link, SET the address, rejoin. Serialised. */
static int apply(const uint8_t *m, const char *why)
{
	WqMacStatus st;
	int was_connected = 0;
	memset(&st, 0, sizeof(st));
	if (g_mtx >= 0) sceKernelLockMutex(g_mtx, 1, NULL);
	int r = ensure_ctx(&st);
	if (r == WQ_OK) {
		note_factory(&st);
		was_connected = netctl_state() == 3;
		if (was_connected) {
			wq_net_disconnect();
			for (int i = 0; i < 40 && netctl_state() == 3; i++)
				sceKernelDelayThread(200 * 1000);
		}
		unsigned m0, m1;
		split(m, &m0, &m1);
		for (int i = 0; i < 80; i++) {              /* refused while busy/initialising */
			r = wqMacAddr(WQ_MAC_OP_SET, m0, m1, &st);
			if (r == WQ_OK || r == WQ_ERR_ARG || r == WQ_ERR_RESOLVE)
				break;
			sceKernelDelayThread(250 * 1000);
		}
		/* Always kick a join: after a wake or radio cycle the shell's own
		 * retry is slower (5 s rejoin, 12 s IcmConnect); IcmConnect is
		 * ignored while a join is already under way. */
		wq_net_icm_connect();
		if (r == WQ_OK)
			g_applied_powerups = st.powerups;
		g_retry = (r != WQ_OK && r != WQ_ERR_ARG);
	}
	if (g_mtx >= 0) sceKernelUnlockMutex(g_mtx, 1);
	char line[200], *p = line, *end = line + sizeof(line);
	p = put(p, end, "mac: ");      p = put(p, end, why);
	p = put(p, end, " ");          p = put_mac(p, end, m);
	p = put(p, end, r == WQ_OK ? " OK" : " FAILED");
	p = put(p, end, " (rc ");      p = put_hex(p, end, (unsigned)st.last_rc);
	p = put(p, end, " chip ");     p = put_mac(p, end, st.live);
	p = put(p, end, " ctl ");      p = put_u(p, end, st.ctl_check);
	p = put(p, end, " walk ");     p = put_u(p, end, st.chain);
	put(p, end, ")");
	if (r == WQ_OK) WQ_LOGI("%s", line); else WQ_LOGW("%s", line);
	return r;
}

/* Re-send the custom address after every chip power-up. The counter is a hook
 * on the driver's post-firmware init; reading it sends nothing to the chip. */
static int factory(uint8_t *out);

static int watch_thread(SceSize args, void *argp)
{
	static const uint8_t zero[6];
	for (int t = 0;; t++) {
		sceKernelDelayThread(g_fast ? 200 * 1000 : 1000 * 1000);
		if (g_fast && t > 300)                     /* ~60 s after boot */
			g_fast = 0;
		WqMacStatus st;
		/* Learn the console's own address once connected, whatever the mode:
		 * the Settings page shows it in Default and Randomize builds on it. */
		if (!memcmp(g_saved_factory, zero, 6) && !g_job_busy && netctl_state() == 3) {
			if (g_mtx >= 0) sceKernelLockMutex(g_mtx, 1, NULL);
			if (ensure_ctx(&st) == WQ_OK)
				note_factory(&st);
			if (g_mtx >= 0) sceKernelUnlockMutex(g_mtx, 1);
		}
		if (g_job_busy)
			continue;
		/* A refused SET (driver busy) is retried until the chip confirms it:
		 * the saved setting must not claim an address the chip is not using. */
		if (g_retry && radio_on()) {
			static int tick;
			if (++tick % 5 == 0) {
				uint8_t f[6];
				if (g_mode == 1)
					apply(g_custom, "retry");
				else if (factory(f) == WQ_OK)
					apply(f, "retry stock");
			}
			continue;
		}
		if (g_mode != 1)
			continue;
		if (wqMacAddr(WQ_MAC_OP_STATUS, 0, 0, &st) != WQ_OK)
			continue;
		if (st.powerups == g_applied_powerups || !radio_on())
			continue;
		WQ_LOGI("mac: chip powered up (%u) - %s the custom address", (unsigned)st.powerups,
		        g_fast ? "sending (before the first join)" : "re-sending");
		if (apply(g_custom, "power-up") != WQ_OK)
			g_applied_powerups = st.powerups;          /* do not loop on a refusal */
	}
	return 0;
}

static void watch_start(void)
{
	if (g_mtx < 0)
		g_mtx = sceKernelCreateMutex("WqMacMtx", 0, 0, NULL);
	if (g_watch_started)
		return;
	SceUID t = sceKernelCreateThread("WqMacWatch", watch_thread, 0x40, 0x2000, 0, 0, NULL);
	if (t >= 0 && sceKernelStartThread(t, 0, NULL) >= 0)
		g_watch_started = 1;
}

static int job_thread(SceSize args, void *argp)
{
	if (g_job_boot) {
		/* Send the address at a chip power-up before the first join, so the
		 * console connects once: the RX buffer preset's boot cycle if there
		 * is one, else our own (the watcher sends on the power-up). Only if
		 * the link wins anyway is it the usual drop / SET / rejoin. */
		WqMacStatus st;
		int started = 0;
		for (int i = 0; i < MAC_BOOT_WAIT_S * 5; i++) {
			if (wqMacAddr(WQ_MAC_OP_STATUS, 0, 0, &st) == WQ_OK && st.powerups > 0) {
				g_job_busy = 0;                  /* the watcher sends it */
				return sceKernelExitDeleteThread(0);
			}
			if (netctl_state() == 3 && !g_boot_rx_cycle)
				break;                           /* joined first: drop / SET / rejoin */
			if (!started && !g_boot_rx_cycle && radio_on()) {
				sceKernelDelayThread(1000 * 1000);
				if (netctl_state() != 3 && rxcycle_start_ex(0, 0, NULL) == WQ_OK) {
					started = 1;
					WQ_LOGI("mac: boot - radio power-cycle so the address is set before the first join");
				}
			}
			sceKernelDelayThread(200 * 1000);
		}
		g_fast = 0;
	} else {
		sceKernelDelayThread(2 * 1000 * 1000);      /* let the reply/Settings settle */
	}
	if (radio_on())
		apply(g_job_mac, g_job_boot ? "boot" : g_mode ? "custom" : "stock");
	else
		WQ_LOGI("mac: radio off - the address goes to the chip when it powers up");
	/* The setting moved on while this one ran: the watcher sends the newest. */
	const uint8_t *want = g_mode == 1 ? g_custom : g_saved_factory;
	if (memcmp(g_job_mac, want, 6))
		g_retry = 1;
	g_job_busy = 0;
	return sceKernelExitDeleteThread(0);
}

static int start_job(const uint8_t *m, int boot)
{
	watch_start();
	if (g_job_busy)
		return WQ_ERR_BUSY;
	g_job_busy = 1;
	memcpy(g_job_mac, m, 6);
	g_job_boot = boot;
	SceUID t = sceKernelCreateThread("WqMacJob", job_thread, 0x40, 0x2000, 0, 0, NULL);
	if (t < 0 || sceKernelStartThread(t, 0, NULL) < 0) {
		g_job_busy = 0;
		return WQ_ERR_NOT_READY;
	}
	return WQ_OK;
}

/* The console's own address, or WQ_ERR_NOT_READY. */
static int factory(uint8_t *out)
{
	static const uint8_t zero[6];
	if (memcmp(g_saved_factory, zero, 6)) {
		memcpy(out, g_saved_factory, 6);
		return WQ_OK;
	}
	WqMacStatus st;
	if (ensure_ctx(&st) != WQ_OK || !st.have_factory)
		return WQ_ERR_NOT_READY;
	note_factory(&st);
	memcpy(out, st.factory, 6);
	return WQ_OK;
}

void wq_mac_boot(int mode, unsigned m0, unsigned m1, unsigned f0, unsigned f1, int rx_cycle)
{
	g_mode = mode ? 1 : 0;
	g_boot_rx_cycle = rx_cycle;
	if (g_mode == 1) {
		WqMacStatus st;
		wqMacAddr(WQ_MAC_OP_STATUS, 0, 0, &st);  /* hooks in before the boot power-up */
		g_fast = 1;
	}
	join(g_custom, m0, m1);
	join(g_saved_factory, f0, f1);
	watch_start();
	uint8_t probe[6];
	int why;
	if (g_mode != 1)
		return;
	{
		char t[13], *p = t;
		put_mac_sep(p, t + sizeof(t), g_custom, 0);
		if (wq_mac_parse(t, probe, &why) < 0) {      /* a damaged saved address */
			WQ_LOGW("mac: saved custom address invalid - back to stock");
			g_mode = 0;
			save_state();
			return;
		}
	}
	if (start_job(g_custom, 1) != WQ_OK)
		WQ_LOGW("mac: boot apply not started");
}

/* HUD: 1 and the address while a custom one is in use, else 0. */
int wq_mac_hud(uint8_t mac[6])
{
	if (g_mode != 1)
		return 0;
	memcpy(mac, g_custom, 6);
	return 1;
}

/* ---- commands -------------------------------------------------------------- */

static char *put_status(char *p, char *end, const WqMacStatus *s)
{
	SceNetEtherAddr na;
	memset(&na, 0, sizeof(na));
	int nr = sceNetGetMacAddress(&na, 0);
	p = put(p, end, g_mode ? "mac: custom " : "mac: stock");
	if (g_mode) p = put_mac(p, end, g_custom);
	p = put(p, end, " | chip-now drv ");  p = put_mac(p, end, s->drv);
	p = put(p, end, " wlan0 ");
	if (s->chain == 0) p = put_mac(p, end, s->lladdr);
	else { p = put(p, end, "? (step "); p = put_u(p, end, s->chain); p = put(p, end, ")"); }
	p = put(p, end, " sceNet ");
	if (nr >= 0) p = put_mac(p, end, na.data); else p = put(p, end, "err");
	p = put(p, end, " factory ");
	if (s->have_factory) p = put_mac(p, end, s->factory); else p = put(p, end, "?");
	p = put(p, end, " | ctl ");
	p = put(p, end, s->ctl_check == 0 ? "OK" : s->ctl_check == 2 ? "ENTRY-MISMATCH"
	              : s->ctl_check == 3 ? "BACKPTR-MISMATCH" : "?");
	p = put(p, end, " powerups "); p = put_u(p, end, s->powerups);
	p = put(p, end, " sets ");     p = put_u(p, end, s->sets);
	if (!s->hooked)   p = put(p, end, " | NOT HOOKED");
	if (!s->ctx_seen) p = put(p, end, " | no driver ctx yet");
	return p;
}

int wq_mac_cmd(const char *a, char *out, int outcap)
{
	char *p = out, *end = out + outcap;
	WqMacStatus st;
	memset(&st, 0, sizeof(st));
	out[0] = 0;
	const char *arg = a;
	while (*arg && *arg != ' ') arg++;
	while (*arg == ' ') arg++;
#define IS(w) (strncmp(a, w, sizeof(w) - 1) == 0 && (a[sizeof(w) - 1] == 0 || a[sizeof(w) - 1] == ' '))

	if (!a[0] || IS("status")) {
		int r = wqMacAddr(WQ_MAC_OP_STATUS, 0, 0, &st);
		put_status(p, end, &st);
		return r;
	}
	if (IS("probe")) {
		ensure_ctx(&st);
		int r = wqMacAddr(WQ_MAC_OP_LIVE, 0, 0, &st);
		p = put(p, end, r == WQ_OK ? "mac probe: chip says " : "mac probe: FAILED ");
		if (r == WQ_OK) p = put_mac(p, end, st.live);
		p = put(p, end, " | ");
		put_status(p, end, &st);
		return r;
	}
	if (IS("set") || IS("random") || IS("custom")) {
		uint8_t m[6], f[6];
		if (IS("set")) {
			int why;
			if (wq_mac_parse(arg, m, &why) < 0) {
				p = put(p, end, "mac: refused - ");
				put(p, end, k_why[why]);
				return WQ_ERR_ARG;
			}
		} else {
			if (factory(f) != WQ_OK) {
				put(p, end, "mac: the console's own address is not known yet (connect first)");
				return WQ_ERR_NOT_READY;
			}
			wq_mac_random(m, f);
		}
		g_mode = 1;
		memcpy(g_custom, m, 6);
		save_state();
		int r = start_job(m, 0);
		if (r == WQ_ERR_BUSY) {                    /* a change is still running: */
			g_retry = 1;                           /* the watcher sends this next */
			r = WQ_OK;
		}
		p = put(p, end, "mac: custom ");
		p = put_mac(p, end, m);
		put(p, end, r == WQ_OK ? " - Wi-Fi drops and rejoins" : " - saved, not applied");
		return r;
	}
	if (IS("stock")) {
		uint8_t f[6];
		int was = g_mode;
		g_mode = 0;
		save_state();
		wqMacAddr(WQ_MAC_OP_STATUS, 0, 0, &st);
		if (!was && st.sets == 0) {
			put(p, end, "mac: stock (already in use)");
			return WQ_OK;
		}
		if (factory(f) != WQ_OK) {
			put(p, end, "mac: stock saved; it applies after a restart");
			return WQ_OK;
		}
		int r = start_job(f, 0);
		if (r == WQ_ERR_BUSY) {
			g_retry = 1;
			r = WQ_OK;
		}
		p = put(p, end, "mac: stock ");
		p = put_mac(p, end, f);
		put(p, end, r == WQ_OK ? " - Wi-Fi drops and rejoins" : " - saved, not applied");
		return r;
	}
	if (IS("cycle")) {
		if (!radio_on()) {
			put(p, end, "mac: radio is off");
			return WQ_OK;
		}
		int c = rxcycle_start_ex(0, netctl_state() == 3, NULL);
		put(p, end, c == WQ_OK ? "mac: power-cycling the radio (~20 s)"
		                       : "mac: power-cycle NOT started (busy?)");
		return c;
	}
#undef IS
	put(p, end, "usage: mac status|probe|stock|custom|random|set <addr>|cycle");
	return WQ_ERR_ARG;
}
